-- --- vendors & bank accounts (§3.8, accounting-design.md §8) ------------------------------------
ALTER TABLE vendors
  ADD CONSTRAINT ck_vendors__tax_id CHECK (tax_id ~ '^[0-9]{13}$'),
  ADD CONSTRAINT ck_vendors__branch_code CHECK (branch_code ~ '^[0-9]{5}$'),
  ADD CONSTRAINT ck_vendors__postcode CHECK (postcode IS NULL OR postcode ~ '^[0-9]{5}$'),
  ADD CONSTRAINT ck_vendors__payment_terms_days CHECK (payment_terms_days >= 0);

ALTER TABLE vendor_bank_accounts
  ADD CONSTRAINT ck_vendor_bank_accounts__last4 CHECK (account_no_last4 ~ '^[0-9]{4}$'),
  ADD CONSTRAINT ck_vendor_bank_accounts__hash CHECK (octet_length(account_no_hash) = 32),
  ADD CONSTRAINT ck_vendor_bank_accounts__active CHECK (status NOT IN ('active', 'superseded') OR (effective_from IS NOT NULL AND decided_at IS NOT NULL));

-- A bank account is never edited in place: pending → active | rejected (with the approval data),
-- active → superseded; nothing else changes and decided rows cannot be deleted.
CREATE FUNCTION check_vendor_bank_account_change() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'vendor_bank_accounts rows are never deleted' USING ERRCODE = 'restrict_violation';
  END IF;
  IF (NEW.vendor_id, NEW.bank_code, NEW.branch_name, NEW.account_name, NEW.account_no_enc, NEW.account_no_last4, NEW.account_no_hash)
     IS DISTINCT FROM (OLD.vendor_id, OLD.bank_code, OLD.branch_name, OLD.account_name, OLD.account_no_enc, OLD.account_no_last4, OLD.account_no_hash) THEN
    RAISE EXCEPTION 'vendor_bank_accounts % is never edited in place; propose a new account', OLD.id USING ERRCODE = 'restrict_violation';
  END IF;
  IF NOT (
       (OLD.status = 'pending_approval' AND NEW.status IN ('pending_approval', 'active', 'rejected'))
    OR (OLD.status = 'active' AND NEW.status IN ('active', 'superseded'))
    OR (OLD.status = NEW.status AND OLD.status IN ('superseded', 'rejected'))
  ) THEN
    RAISE EXCEPTION 'vendor_bank_accounts %: % → % is not allowed', OLD.id, OLD.status, NEW.status USING ERRCODE = 'restrict_violation';
  END IF;
  IF OLD.status <> 'pending_approval' AND (NEW.verification_call, NEW.approval_request_id, NEW.effective_from)
     IS DISTINCT FROM (OLD.verification_call, OLD.approval_request_id, OLD.effective_from) THEN
    RAISE EXCEPTION 'vendor_bank_accounts %: decided rows keep their approval data', OLD.id USING ERRCODE = 'restrict_violation';
  END IF;
  RETURN NEW;
END
$$;
CREATE TRIGGER tg_vendor_bank_accounts__immutable BEFORE UPDATE OR DELETE ON vendor_bank_accounts
  FOR EACH ROW EXECUTE FUNCTION check_vendor_bank_account_change();

