-- --- factories & onboarding (D-011, D-041) ------------------------------------------------------
ALTER TABLE factories
  ADD CONSTRAINT ck_factories__code CHECK (code ~ '^[A-Z0-9][A-Z0-9-]*$'),
  ADD CONSTRAINT ck_factories__tax_id CHECK (tax_id ~ '^[0-9]{13}$'),
  ADD CONSTRAINT ck_factories__branch_code CHECK (branch_code ~ '^[0-9]{5}$'),
  ADD CONSTRAINT ck_factories__trial_jobs CHECK (trial_jobs_completed >= 0),
  ADD CONSTRAINT ck_factories__offboarded CHECK (status <> 'offboarded' OR offboarded_at IS NOT NULL),
  ADD CONSTRAINT ck_factories__active CHECK (status <> 'active' OR activated_at IS NOT NULL);

-- The partner lifecycle graph; `trial → active` needs a passed site visit and an approved
-- `partner_activation` request for this factory (D-041). The service checks first; this is the backstop.
CREATE FUNCTION check_factory_status_change() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF NEW.status = OLD.status THEN
    RETURN NEW;
  END IF;
  IF NOT (
       (OLD.status = 'applied' AND NEW.status IN ('under_review', 'offboarded'))
    OR (OLD.status = 'under_review' AND NEW.status IN ('applied', 'trial', 'offboarded'))
    OR (OLD.status = 'trial' AND NEW.status IN ('active', 'suspended', 'offboarded'))
    OR (OLD.status = 'active' AND NEW.status IN ('suspended', 'offboarded'))
    OR (OLD.status = 'suspended' AND NEW.status IN ('trial', 'active', 'offboarded'))
  ) THEN
    RAISE EXCEPTION 'factories %: % → % is not allowed', OLD.id, OLD.status, NEW.status USING ERRCODE = 'check_violation';
  END IF;
  IF OLD.status = 'trial' AND NEW.status = 'active' THEN
    IF NOT EXISTS (SELECT 1 FROM site_visits WHERE factory_id = NEW.id AND result = 'pass') THEN
      RAISE EXCEPTION 'factories %: a passed site visit is required before activation (D-041)', NEW.id USING ERRCODE = 'check_violation';
    END IF;
    IF NOT EXISTS (
      SELECT 1 FROM approval_requests r JOIN approval_policies p ON p.id = r.policy_id
       WHERE p.key = 'partner_activation' AND r.subject_type = 'factory' AND r.subject_id = NEW.id AND r.status = 'approved'
    ) THEN
      RAISE EXCEPTION 'factories %: an approved partner_activation request is required (D-041)', NEW.id USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  NEW.status_changed_at := now();
  RETURN NEW;
END
$$;
CREATE TRIGGER tg_factories__status BEFORE UPDATE OF status ON factories
  FOR EACH ROW EXECUTE FUNCTION check_factory_status_change();

